{"command":"python3 -c "
import re, statistics
def medians(path, variants, sizes):
    rows={}
    for line in open(path):
        m=re.match(r'vllm rep\d+\s+(\S+) rows\s+(\d+):\s+([\d.]+) ms/step', line)
        if m and m.group(1) in variants and int(m.group(2)) in sizes:
            rows.setdefault((m.group(1),int(m.group(2))),[]).append(float(m.group(3)))
    return {k: (statistics.median(v), min(v), max(v), len(v)) for k,v in sorted(rows.items())}
r2=medians('results/runs/2026-11-04-muse-round-2/console-vllm.txt',{'base','muse-all','muse-routing','muse-combine','round1-all'},[1,8,32])
for (v,s),(med,lo,hi,n) in r2.items():
    base=r2[('base',s)][0]
    print(f'{v:14s} rows {s:2d}: med {med:7.3f}  d={med-base:+.3f}  (n={n})')
print()
r1=medians('results/runs/2026-11-04-muse-round-1/console-vllm.txt',{'base','muse-all'},[1,8,32])
for (v,s),(med,lo,hi,n) in r1.items():
    base=r1[('base',s)][0]
    print(f'{v:10s} rows {s:2d}: med {med:7.3f}  d={med-base:+.3f}  (n={n})')
"","description":"Recompute G3 medians from console files"}

