{"content":""""Claim-contract validator (DESIGNER-B PROTOTYPE — design scaffolding, not shipped).

The shipped mechanism is the checker agent + the contract text; this script
exists to prove the contract is mechanical: every rule below is a file read,
a key lookup, or a string match a checklist can perform.

Claim file schema (JSON):
  {"doc": "...", "candidate": {"attempt_dir": "...", "eval_dir": "..."},
   "claims": [{"id", "text", "kind": "measured"|"predicted",
               "level": "piece"|"request"|null, "slots": [...],
               "value": number|string, "source": {...}, "inputs": [...],
               "formula": "...", "residual": "..."}],
   "unverified": ["..."], "required_unverified": ["keyword", ...]}

Rules (each returns defect strings; no defects = pass):
  R1 level integrity: measured/request cites only submit.json (+ its jsonl);
     a grader verdict file can never source a request-level claim.
  R2 measured/piece: cites a grader verdict file (--out JSON) + existing key;
     the value equals the file's (verbatim, 1e-9).
  R3 measured/request: cites submit.json verdict key (value match) + a jsonl
     cell (variant, setting) with exactly 5 runs.
  R4 predicted: has inputs[], formula, residual; every file input resolves to
     the candidate's own attempt dir or eval dir (own measured effect only).
  R5 combination: a measured claim spanning >1 slot cites muse-all.
  R6 unverified: every required keyword appears in some bullet; no claim text
     says free/neutral/invisible about an unmeasured cost.
"""

import json
import sys
from pathlib import Path


def getpath(doc, dotted):
    cur = doc
    for part in dotted.split("."):
        if not isinstance(cur, dict) or part not in cur:
            return None, False
        cur = cur[part]
    return cur, True


def is_grader_file(doc):
    return isinstance(doc, dict) and "timing_us_per_layer" in doc and "g1" in doc


def is_submit_file(doc):
    return isinstance(doc, dict) and doc.get("check") == "submit"


def check_claim(c, candidate, repo):
    d = []
    kind, level = c.get("kind"), c.get("level")
    slots = c.get("slots", [])
    src = c.get("source", {})

    if kind == "measured" and level == "piece":
        f = repo / src.get("file", "")
        if not f.exists():
            d.append(f"R2 {c['id']}: no verdict file {src.get('file')} "
                     f"(builder must grade with --out)")
            return d
        doc = json.loads(f.read_text())
        if not is_grader_file(doc):
            d.append(f"R2 {c['id']}: {src.get('file')} is not a grader verdict")
            return d
        v, ok = getpath(doc, src.get("key", ""))
        if not ok:
            d.append(f"R2 {c['id']}: key {src.get('key')} not in verdict")
        elif isinstance(c.get("value"), (int, float)) and abs(v - c["value"]) > 1e-9:
            d.append(f"R2 {c['id']}: value {c['value']} != file {v}")

    elif kind == "measured" and level == "request":
        f = repo / src.get("verdict_file", "")
        if not f.exists():
            d.append(f"R1/R3 {c['id']}: no submit file {src.get('verdict_file')}")
        else:
            doc = json.loads(f.read_text())
            if is_grader_file(doc):
                d.append(f"R1 {c['id']}: LEVEL VIOLATION — a grader verdict "
                         f"cannot source a request-level claim")
            elif not is_submit_file(doc):
                d.append(f"R3 {c['id']}: {src.get('verdict_file')} is not a submit.json")
            else:
                v, ok = getpath(doc, src.get("verdict_key", ""))
                if not ok:
                    d.append(f"R3 {c['id']}: key {src.get('verdict_key')} not in submit")
                elif v != c.get("value"):
                    d.append(f"R3 {c['id']}: value {c['value']!r} != file {v!r}")
        log = repo / src.get("log_file", "")
        if "variant" in src and "setting" in src:
            if not log.exists():
                d.append(f"R3 {c['id']}: no log {src.get('log_file')}")
            else:
                rows, prompt = src["setting"]
                n = sum(1 for line in log.open()
                        if (lambda r: r.get("kind") == "run" and r.get("engine") == "vllm"
                           and (r.get("variant"), r.get("rows"), r.get("prompt"))
                           == (src["variant"], rows, prompt))(json.loads(line)))
                if n != 5:
                    d.append(f"R3 {c['id']}: cell {src['variant']}@{rows}x{prompt} "
                             f"has {n} runs, want 5")
        if len(slots) > 1 and "muse-all" not in json.dumps(src):
            d.append(f"R5 {c['id']}: COMBINATION — a measured {len(slots)}-slot claim "
                     f"must cite a muse-all row")

    elif kind == "predicted":
        for req in ("inputs", "formula", "residual"):
            if not c.get(req):
                d.append(f"R4 {c['id']}: prediction needs {req}")
        if not c.get("inputs"):
            return d
        own = [candidate.get("attempt_dir", ""), candidate.get("eval_dir", "")]
        for i in c["inputs"]:
            if "claim" in i:
                continue  # chained to another checked claim in this doc
            p = i.get("file", "")
            if not any(p.startswith(o) for o in own if o):
                d.append(f"R4 {c['id']}: BORROWED input {p} — predictions count "
                         f"only the candidate's own measured effect")
    else:
        d.append(f"{c['id']}: kind/level must be measured+piece, measured+request, "
                 f"or predicted (got {kind}+{level})")

    low = c.get("text", "").lower()
    if any(w in low for w in (" free", "neutral", "invisible")) and kind == "measured":
        d.append(f"R6 {c['id']}: assumption language about an unmeasured cost")
    return d


def check_doc(path, repo):
    spec = json.loads(Path(path).read_text())
    defects = []
    for c in spec.get("claims", []):
        defects += check_claim(c, spec.get("candidate", {}), Path(repo))
    bullets = " ".join(spec.get("unverified", [])).lower()
    for kw in spec.get("required_unverified", []):
        if kw.lower() not in bullets:
            defects.append(f"R6 unverified: missing '{kw}' (never assume free/neutral)")
    return defects


if __name__ == "__main__":
    repo = sys.argv[2] if len(sys.argv) > 2 else "."
    defects = check_doc(sys.argv[1], repo)
    print("\n".join(defects) if defects else "pass: every claim resolves")
    sys.exit(1 if defects else 0)
