{"content":""""Pinned in-round end-to-end gate for the Muse agent swarm (PROTOTYPE).

Designer-c prototype of the proposed `bench/grader/check_ready.py`. It runs
exactly one thing: `time_candidates.py vllm` with the G3 protocol pinned
(4 G3 settings, 5 repeats, 256 tokens, positional slots only, no --variant),
then audits the produced log instead of trusting it:

  1. exactly one ready-protocol marker, with the pinned values;
  2. every run is engine vllm, at the 4 G3 settings, 5 repeats each, no extras;
  3. the variant set is exactly base + compiled-<slot> + muse-<slot>
     (+ compiled-all/muse-all when >1 slot);
  4. every non-base variant keeps base's greedy tokens (exact, rows 1 and 32);
  5. the g3 verdict is RECOMPUTED from the log and must match g3-vllm.json;
  6. every submitted muse-<slot> (and muse-all, when present) passes G3
     against base and against its compiled counterpart.

Usage (GPU run; takes the GPU lock via time_candidates, waits its turn):

  .venv/bin/python check_ready.py <out-dir> SLOT=FOLDER [SLOT=FOLDER...]

Audit only (no GPU; also useful post-round):

  .venv/bin/python check_ready.py --audit <out-dir>

Exit codes: 0 pass, 1 judged fail (files written), 2 protocol violation.
Every failure path still writes ready-verdict.json, so a checker can cite it.
"""

import contextlib
import io
import json
import sys
from datetime import datetime, timezone
from pathlib import Path

HERE = Path(__file__).resolve().parent
GRADER = HERE  # prototype dir; real home: bench/grader (imports work the same)
# Import the real tools from the worktree's bench/grader + bench/micro.
WORKTREE = HERE.parents[2]
sys.path.insert(0, str(WORKTREE / "bench" / "grader"))
sys.path.insert(0, str(WORKTREE / "bench" / "micro"))
import time_candidates as tc  # noqa: E402

PINNED_SETTINGS = [(1, 128), (8, 128), (32, 128), (32, 1024)]
PINNED_REPEATS = 5
PINNED_TOKENS = 256
PINNED_ENGINE = "vllm"
MARKER_KIND = "ready-protocol"


def utcnow():
    return datetime.now(timezone.utc).strftime("%FT%TZ")


def expected_variants(slots):
    names = ["base"]
    for s in slots:
        names.append(f"compiled-{s}")
        names.append(f"muse-{s}")
    if len(slots) > 1:
        names += ["compiled-all", "muse-all"]
    return names


def judged_variants(slots):
    names = [f"muse-{s}" for s in slots]
    if len(slots) > 1:
        names.append("muse-all")
    return names


def audit(outdir):
    """Audit <outdir>'s log + g3 file. Returns (verdict_dict, exit_code)."""
    outdir = Path(outdir)
    log = outdir / f"muse-{PINNED_ENGINE}.jsonl"
    g3file = outdir / "g3-vllm.json"
    problems = []  # protocol violations -> exit 2
    fails = []  # judged failures -> exit 1
    verdict = {
        "audited_at": utcnow(),
        "out": str(outdir),
        "protocol": {
            "engine": PINNED_ENGINE,
            "settings": [f"{r}x{p}" for r, p in PINNED_SETTINGS],
            "repeats": PINNED_REPEATS,
            "tokens": PINNED_TOKENS,
        },
    }

    if not log.exists():
        problems.append(f"missing log file {log}")
        verdict.update({"pass": False, "problems": problems, "fails": fails})
        return verdict, 2
    records = [json.loads(line) for line in log.read_text().splitlines() if line.strip()]
    markers = [r for r in records if r.get("kind") == MARKER_KIND]
    if len(markers) != 1:
        problems.append(f"want exactly 1 {MARKER_KIND} marker, found {len(markers)}")
        verdict.update({"pass": False, "problems": problems, "fails": fails})
        return verdict, 2
    m = markers[0]
    for key, want in (
        ("engine", PINNED_ENGINE),
        ("settings", [[r, p] for r, p in PINNED_SETTINGS]),
        ("repeats", PINNED_REPEATS),
        ("tokens", PINNED_TOKENS),
    ):
        if m.get(key) != want:
            problems.append(f"marker {key} is {m.get(key)!r}, want {want!r}")
    slots = m.get("slots", [])
    if not slots:
        problems.append("marker names no slots")
        slots = []
    verdict["protocol"]["slots"] = slots
    verdict["protocol"]["attempts"] = m.get("attempts", {})

    runs = [r for r in records if r.get("kind") == "run"]
    checks = [r for r in records if r.get("kind") == "check"]
    if not runs:
        problems.append("log holds no runs")
    for r in runs:
        if r.get("engine") != PINNED_ENGINE:
            problems.append(f"run with engine {r.get('engine')!r}, want vllm only")
            break
    want_settings = set(PINNED_SETTINGS)
    got_settings = {(r["rows"], r["prompt"]) for r in runs}
    if got_settings != want_settings:
        problems.append(
            f"settings are {sorted(got_settings)}, want {sorted(want_settings)}"
        )
    want_names = set(expected_variants(slots))
    got_names = {r["variant"] for r in runs}
    if got_names != want_names:
        problems.append(f"variants are {sorted(got_names)}, want {sorted(want_names)}")
    for name in sorted(got_names & want_names):
        for setting in sorted(want_settings):
            reps = sorted(
                r["rep"]
                for r in runs
                if r["variant"] == name and (r["rows"], r["prompt"]) == setting
            )
            if reps != list(range(PINNED_REPEATS)):
                problems.append(f"{name} {setting}: reps {reps}, want 0..4")
    if problems:
        verdict.update({"pass": False, "problems": problems, "fails": fails})
        return verdict, 2

    # Token exactness: every non-base variant, rows 1 and 32 (brief's G2 end to end).
    exact = {}
    for name in sorted(got_names - {"base"}):
        rows_exact = {}
        for rows in (1, 32):
            recs = [
                c for c in checks if c.get("variant") == name and c.get("rows") == rows
            ]
            ok = bool(recs) and all(c.get("exact") for c in recs)
            rows_exact[str(rows)] = ok
            if not ok:
                fails.append(f"{name} changes base's greedy tokens at rows={rows}")
        exact[name] = rows_exact
    verdict["exact"] = exact

    # Recompute G3 from the log; the g3 file must match (kills lazy forgery).
    if not g3file.exists():
        problems.append(f"missing {g3file}")
        verdict.update({"pass": False, "problems": problems, "fails": fails})
        return verdict, 2
    filed = json.loads(g3file.read_text())
    tmp = outdir / "g3-recomputed-tmp.json"
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        tc.g3(log, sorted(got_names), PINNED_SETTINGS, tmp)
    recomputed = json.loads(tmp.read_text())
    tmp.unlink()
    for name in judged_variants(slots):
        if filed.get(name) != recomputed.get(name):
            problems.append(f"g3-vllm.json entry for {name} differs from log recompute")
    if problems:
        verdict.update({"pass": False, "problems": problems, "fails": fails})
        return verdict, 2

    submitted = {}
    for name in judged_variants(slots):
        entry = recomputed.get(name, {})
        g3pass = entry.get("g3", False)
        submitted[name] = {
            "g3": g3pass,
            "vs": {
                bar: v.get("pass") for bar, v in entry.items() if bar != "g3"
            },
            "phases": {bar: v.get("phases") for bar, v in entry.items() if bar != "g3"},
        }
        if not g3pass:
            fails.append(f"{name} fails G3")
    verdict["submitted"] = submitted
    ok = not fails
    verdict.update({"pass": ok, "problems": problems, "fails": fails})
    return verdict, 0 if ok else 1


def run(outdir, attempts):
    outdir = Path(outdir)
    if outdir.exists() and any(outdir.iterdir()):
        print(f"{outdir}: exists and is not empty; use a fresh folder per check")
        return 2
    slots = [s for s, _ in attempts]
    # Pinned invocation: no --variant, no --repeats/--settings/--tokens flags.
    sys.argv = ["time_candidates.py", PINNED_ENGINE, str(outdir)] + [
        f"{s}={f}" for s, f in attempts
    ]
    tc.main()  # takes the GPU lock itself; waits its turn; loads the model inside
    marker = {
        "kind": MARKER_KIND,
        "engine": PINNED_ENGINE,
        "settings": [[r, p] for r, p in PINNED_SETTINGS],
        "repeats": PINNED_REPEATS,
        "tokens": PINNED_TOKENS,
        "slots": slots,
        "attempts": {s: str(f) for s, f in attempts},
        "exact_required": True,
        "written_at": utcnow(),
    }
    with (outdir / f"muse-{PINNED_ENGINE}.jsonl").open("a") as f:
        f.write(json.dumps(marker) + "\n")
    return finish(outdir)


def finish(outdir):
    outdir = Path(outdir)
    verdict, code = audit(outdir)
    (outdir / "ready-verdict.json").write_text(json.dumps(verdict, indent=1) + "\n")
    for p in verdict.get("problems", []):
        print(f"PROTOCOL: {p}")
    for f in verdict.get("fails", []):
        print(f"FAIL: {f}")
    for name, v in (verdict.get("submitted") or {}).items():
        print(f"ready {name}: {'pass' if v['g3'] else 'fail'} {v['vs']}")
    print(f"ready check: {'PASS' if verdict['pass'] else 'FAIL'} (exit {code})")
    return code


def main(argv):
    if len(argv) == 3 and argv[1] == "--audit":
        return finish(Path(argv[2]))
    if len(argv) < 3 or argv[1].startswith("-"):
        print(__doc__.split("\n\n")[2].replace("check_ready.py", argv[0]))
        return 2
    attempts = []
    for spec in argv[2:]:
        slot, sep, folder = spec.partition("=")
        if not sep or slot not in ("routing", "combine", "routing+combine", "experts"):
            print(f"{spec!r}: give SLOT=FOLDER")
            return 2
        attempts.append((slot, folder))
    if len({s for s, _ in attempts}) != len(attempts):
        print("each slot at most once per check")
        return 2
    return run(Path(argv[1]), attempts)


if __name__ == "__main__":
    sys.exit(main(sys.argv))
