{"content":""""Tester-a noise test part 2 + catch numbers (CPU on the live 5-repeat log).

1. Measured deltas vs Claude's post-round figures (findings/muse-round-2.md).
2. Repeat spreads per setting (5 reps).
3. Verdict stability: g3 logic on reps {0,1,2} vs {0..4} (3-vs-5 flips).
4. Boundary cells (same/thin margins) in the live log.
Logic mirrors bench/grader/time_candidates.py:163-197.
"""
import json
import statistics as st
from pathlib import Path

HERE = Path(__file__).resolve().parent
LOG = HERE / "catch" / "muse-vllm.jsonl"
MEASURES = {"decode": "period_median_ms", "prompt": "prompt_ms",
            "request": "wall_ms"}


def against(c, b):
    return "faster" if c[1] < b[0] else "slower" if c[0] > b[1] else "same"


runs = [json.loads(li) for li in LOG.read_text().splitlines()
        if json.loads(li)["kind"] == "run"]
checks = [json.loads(li) for li in LOG.read_text().splitlines()
          if json.loads(li)["kind"] == "check"]
settings = sorted({(r["rows"], r["prompt"]) for r in runs})
variants = sorted({r["variant"] for r in runs})
print(f"runs={len(runs)} variants={variants}")
print(f"settings={settings} reps={sorted({r['rep'] for r in runs})}")
print("checks exact:",
      {(c["variant"], c["rows"]): c.get("exact") for c in checks
       if c["variant"].startswith("muse-")})
print()


def vals(name, rows, prompt, key, reps):
    return [r[key] for r in runs if (r["variant"], r["rows"], r["prompt"],
                                     r["rep"]) == (name, rows, prompt, r["rep"])
            and r["rep"] in reps]


def med(name, rows, prompt, key, reps):
    return st.median(vals(name, rows, prompt, key, reps))


REPS5 = set(range(5))
print("== 1. key deltas (median of 5) vs Claude's post-round figures ==")
for rows, prompt in settings:
    b = med("base", rows, prompt, "prompt_ms", REPS5)
    m = med("muse-routing", rows, prompt, "prompt_ms", REPS5)
    print(f"muse-routing prompt {rows}x{prompt}: {m:.1f} vs base {b:.1f} "
          f"= x{m/b:.3f} (Claude §5: 1.07/1.09/1.10/1.10x)")
for rows, prompt in [(32, 128)]:
    b = med("base", rows, prompt, "period_median_ms", REPS5)
    m = med("muse-combine", rows, prompt, "period_median_ms", REPS5)
    print(f"muse-combine decode 32x128: {m-b:+.3f} ms vs base "
          f"(Claude §3: +1.051 ms)")
    a = med("muse-all", rows, prompt, "period_median_ms", REPS5)
    print(f"muse-all decode 32x128: {a-b:+.3f} ms vs base "
          f"(Claude §3: +0.527 ms)")
print()
print("== 2. decode spreads per setting, 5 reps ==")
for name in ("base", "compiled-routing", "compiled-combine", "muse-routing",
             "muse-combine", "muse-all"):
    for rows, prompt in settings:
        v = vals(name, rows, prompt, "period_median_ms", REPS5)
        print(f"{name:16s} {rows:2d}x{prompt:4d}: "
              f"{min(v):7.3f}..{max(v):7.3f} "
              f"spread={(max(v)-min(v))/st.mean(v)*100:5.1f}%")
print()
print("== prompt spreads per setting, 5 reps ==")
for name in ("base", "muse-routing", "muse-combine", "muse-all"):
    for rows, prompt in settings:
        v = vals(name, rows, prompt, "prompt_ms", REPS5)
        print(f"{name:16s} {rows:2d}x{prompt:4d}: "
              f"{min(v):9.1f}..{max(v):9.1f} "
              f"spread={(max(v)-min(v))/st.mean(v)*100:5.1f}%")


def verdict(reps):
    """g3-style verdict per judged variant vs its two bars (settings detail)."""
    out = {}
    judged = [n for n in variants if n.startswith("muse-")]
    for name in judged:
        out[name] = {}
        for bar in ("base", "compiled-" + name.removeprefix("muse-")):
            sv = {}
            for rows, prompt in settings:
                sv[f"{rows}x{prompt}"] = {
                    m: against(
                        (min(vals(name, rows, prompt, k, reps)),
                         max(vals(name, rows, prompt, k, reps))),
                        (min(vals(bar, rows, prompt, k, reps)),
                         max(vals(bar, rows, prompt, k, reps))))
                    for m, k in MEASURES.items()}
            phases = {
                m: "faster" if all(v[m] == "faster" for v in sv.values())
                else "slower" if any(v[m] == "slower" for v in sv.values())
                else "not slower" for m in MEASURES}
            out[name][bar] = {
                "pass": "faster" in (phases["decode"], phases["prompt"])
                and "slower" not in phases.values(),
                "phases": phases, "settings": sv}
        out[name]["g3"] = all(v["pass"] for k, v in out[name].items()
                              if k != "g3")
    return out


v3, v5 = verdict({0, 1, 2}), verdict(REPS5)
# cross-check recompute vs the real g3 file
g3 = json.loads((HERE / "catch" / "g3-vllm.json").read_text())
match = all(v5[n][b]["pass"] == g3[n][b]["pass"]
            and v5[n][b]["phases"] == g3[n][b]["phases"]
            for n in v5 for b in ("base", "compiled-" + n.removeprefix("muse-")))
print()
print(f"== 3. recompute cross-check vs g3-vllm.json: "
      f"{'MATCH' if match else 'MISMATCH'} ==")
flips = []
for n in v5:
    for b in v5[n]:
        if b == "g3":
            if v3[n]["g3"] != v5[n]["g3"]:
                flips.append((n, b, v3[n]["g3"], v5[n]["g3"]))
            continue
        if v3[n][b]["pass"] != v5[n][b]["pass"]:
            flips.append((n, b, v3[n][b]["pass"], v5[n][b]["pass"]))
        for s in v3[n][b]["settings"]:
            for m in MEASURES:
                a, f = v3[n][b]["settings"][s][m], v5[n][b]["settings"][s][m]
                if a != f:
                    flips.append((f"{n} vs {b} {s} {m}", a, f, ""))
print(f"3-rep vs 5-rep flips: {len(flips)}")
for f in flips:
    print("  flip:", f)
print()
print("== 4. boundary cells in live 5-rep verdict (same or thin) ==")
n_bound = 0
for n in v5:
    for b in ("base", "compiled-" + n.removeprefix("muse-")):
        for (rows, prompt), s in zip(settings, v5[n][b]["settings"]):
            for m, k in MEASURES.items():
                cv = vals(n, rows, prompt, k, REPS5)
                bv = vals(b, rows, prompt, k, REPS5)
                v = against((min(cv), max(cv)), (min(bv), max(bv)))
                gap = (min(bv) - max(cv) if v == "faster"
                       else min(cv) - max(bv) if v == "slower" else 0.0)
                spread = max(max(cv) - min(cv), max(bv) - min(bv))
                if v == "same" or abs(gap) < spread:
                    n_bound += 1
                    tag = "BOUNDARY" if v == "same" else "thin"
                    print(f"  {tag}: {n} vs {b} {s} {m}={v} "
                          f"gap={gap:+.3f}ms spread={spread:.3f}ms")
print(f"{n_bound} boundary/thin cells (of 72)")
","path":"design-lab/tester-a/noise_live.py"}

{"command":".venv/bin/python -c "
import json
for s in ('experts','routing','combine'):
    d=json.load(open(f'results/runs/2026-11-04-muse-round-2/grade-phases-{s}-attempt-{7 if s==\"experts\" else 4 if s==\"routing\" else 1}.json'))
    t=d['timing_us_per_layer']
    print('===',s,'beats_compiled=',d['beats_compiled'],'phases=',d['phases_vs_compiled'])
    for k,v in t.items():
        print(f'  {k}: cand={v[\"candidate\"]} comp={v[\"compiled\"]} x={v[\"candidate\"]/v[\"compiled\"]:.2f} {v[\"vs_compiled\"]}')
"","description":"Record expected grade-phases values for experts"}

