{"content":""""Tester-c noise comparison (no GPU). Extracts decode-step medians and
within-session spreads from ready-check jsonl logs and compares across
sessions: designer T-live routing run, tester-c live combine run, and
Claude's post-round figures (claude/findings/muse-round-2.md:78-83).

Run: .venv/bin/python design-lab/tester-c/tests/noise_compare.py [log.jsonl ...]
"""
import json
import statistics as st
import sys
from pathlib import Path

SETTINGS = [(1, 128), (8, 128), (32, 128), (32, 1024)]
# Claude post-round vLLM medians, muse-round-2.md:78-83 (3 repeats; no 32x1024 in G3).
CLAUDE = {
    "base": {(1, 128): 5.442, (8, 128): 14.524, (32, 128): 30.470},
    "muse-routing": {(1, 128): -0.474, (8, 128): -0.434, (32, 128): -0.537},
    "muse-combine": {(1, 128): -0.372, (8, 128): -0.197, (32, 128): 1.051},
}


def decode_meds(logpath):
    recs = [json.loads(l) for l in Path(logpath).read_text().splitlines() if l.strip()]
    runs = [r for r in recs if r.get("kind") == "run"]
    out = {}
    for v in sorted({r["variant"] for r in runs}):
        for s in SETTINGS:
            vals = [r["period_median_ms"] for r in runs
                    if r["variant"] == v and (r["rows"], r["prompt"]) == s]
            if vals:
                out[(v, s)] = (st.median(vals), min(vals), max(vals), len(vals))
    return out


def main(paths):
    for p in paths:
        print(f"=== {p}")
        m = decode_meds(p)
        for v in sorted({k[0] for k in m}):
            row = []
            for s in SETTINGS:
                if (v, s) in m:
                    med, lo, hi, n = m[(v, s)]
                    row.append(f"{s[0]}x{s[1]}: med={med:.3f} spread={hi-lo:.3f} (n={n})")
            print(f"  {v}: " + " | ".join(row))
        print("  deltas vs base (decode medians):")
        for v in sorted({k[0] for k in m} - {"base"}):
            ds = []
            for s in SETTINGS:
                if (v, s) in m and ("base", s) in m:
                    d = m[(v, s)][0] - m[("base", s)][0]
                    ds.append(f"{s[0]}x{s[1]}: {d:+.3f}")
            print(f"    {v}: " + " ".join(ds))
    print("=== Claude post-round (muse-round-2.md:78-83), 3 repeats")
    for v, ss in CLAUDE.items():
        print(f"  {v}: " + " ".join(f"{s[0]}x{s[1]}: {x:+.3f}" for s, x in sorted(ss.items())))


if __name__ == "__main__":
    main(sys.argv[1:])
