def medians(runs, names, settings):
    """median + [min-max] + n per judged variant/setting/measure, from the
    jsonl run records. Transplant from design B; additive verdict field."""
    out = {}
    for name in names:
        out[name] = {}
        for rows, prompt in settings:
            cell = [
                r for r in runs
                if (r["variant"], r["rows"], r["prompt"]) == (name, rows, prompt)
            ]
            per_measure = {}
            for m, k in tc.MEASURES.items():
                vals = [r[k] for r in cell if r.get(k) is not None]
                per_measure[m] = {
                    "median": statistics.median(vals) if vals else None,
                    "min": min(vals) if vals else None,
                    "max": max(vals) if vals else None,
                    "n": len(cell),
                }
            out[name][f"{rows}x{prompt}"] = per_measure
    return out"}

